Either (a) catch all UPT-typed errors inside `validate()`/`validateEquation()` and convert them to violations (preferred for a library), or (b) add a `thrownError?: Error` field to `ValidationResult` so callers have a single result object to inspect. Option (a) is cleaner:
```typescript
export function validate(expr: ExprNode): ValidationResult {
  const ctx: InferContext = { path: '', violations: [], freeIndices: new Map() };
  let dim: Dimension | null = null;
  try {
    dim = infer(expr, ctx);
  } catch (err) {
    if (err instanceof UPTError) {
      ctx.violations.push({ location: '', expected: DIMENSIONLESS, actual: DIMENSIONLESS, note: String(err) });
    } else throw err;
  }
  return { ok: ctx.violations.length === 0 && dim !== null, inferredDimension: dim ?? null, freeIndices: ctx.freeIndices, violations: ctx.violations };
}
```

